2321	  while (true) {
2322	    shell_printf(VNA_SHELL_PROMPT_STR);
2323	    if (VNAShell_readLine(shell_line, VNA_SHELL_MAX_LENGTH))
2324	      VNAShell_executeLine(shell_line);
