/* shell_split.c —— 示例代码：复现 VNAShell_executeLine 的参数切分 */
#include <stdio.h>
#include <string.h>

int main(void) {
    char line[48] = "scan 1000000 900000000 101 0";
    char *args[8]; int nargs = 0;
    char *lp = line, *ep;
    while (*lp != 0) {
        while (*lp == ' ' || *lp == '\t') lp++;
        ep = (*lp == '"') ? strpbrk(++lp, "\"") : strpbrk(lp, " \t");
        args[nargs++] = lp;
        if ((lp = ep) == NULL) break;
        *lp++ = 0;
    }
    printf("argc = %d\n", nargs - 1);
    for (int i = 0; i < nargs; i++) printf("argv[%d] = \"%s\"\n", i, args[i]);
    return 0;
}
